package main

import "net/http"

func init() {
 // The main server uses this handler at /static/ to serve embedded assets.
}
func staticHandler() http.Handler {
 return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  switch r.URL.Path{
  case "/static/style.css":w.Header().Set("Content-Type","text/css; charset=utf-8");w.Write([]byte(styleCSS))
  case "/static/app.js":w.Header().Set("Content-Type","application/javascript; charset=utf-8");w.Write([]byte(appJS))
  default:http.NotFound(w,r)
  }
 })
}
const styleCSS=`.layout-switch{display:inline-flex;gap:4px;margin-left:auto;background:#101c2f;padding:4px;border-radius:10px;border:1px solid #30425b}.layout-button{white-space:nowrap;background:transparent;color:#9fb0c9;padding:8px 11px;font-size:12px}.layout-button.active{background:#345782;color:#fff}.server-grid{display:grid;gap:12px}.server-grid[data-layout=cards]{grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))}.server-grid[data-layout=compact]{grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr))}.server-grid[data-layout=list]{grid-template-columns:1fr}.server-grid .node{margin:0!important;min-width:0}.server-grid[data-layout=compact] .node{padding:13px}.server-grid[data-layout=compact] .meters{grid-template-columns:1fr;gap:8px}.server-grid[data-layout=list] .node{display:grid;grid-template-columns:minmax(160px,1fr) minmax(280px,2fr);align-items:center;gap:10px 20px}.server-grid[data-layout=list] .node-head{margin:0}.server-grid[data-layout=list] .meta{grid-column:1/-1;margin:0}@media(max-width:650px){.layout-switch{margin-left:0;width:100%;justify-content:space-around}.layout-button{flex:1;padding:8px 4px}.server-grid[data-layout=list] .node{display:block}.server-grid[data-layout=cards],.server-grid[data-layout=compact]{grid-template-columns:1fr}}.view[hidden]{display:none!important}.top-nav{display:flex;gap:6px;background:#0d192c;border-radius:12px;padding:5px}.top-nav button{background:transparent;color:#9aabc5;padding:10px 17px}.top-nav button.selected{background:#29486c;color:#fff}header{gap:16px;flex-wrap:wrap}main{max-width:1200px!important}.view{min-height:62vh}.view>h1,.page-heading h1{font-size:22px;font-weight:650;margin:14px 0 23px}.page-heading{display:flex;align-items:center;justify-content:space-between}.history-panel{margin-top:16px!important}.stats>div{min-height:120px}footer{text-align:center;padding:30px 0}body{background:#0c1423!important}@media(max-width:650px){.top-nav{order:3;width:100%;justify-content:space-around}.top-nav button{padding:9px 12px;flex:1}.page-heading h1{font-size:20px}header h2{margin:0}}#alerts-form{display:flex;flex-wrap:wrap;gap:12px;align-items:center}#alerts-form input,#node-search,#node-group,#node-order{background:#0b1220;color:white;padding:8px;border:1px solid #34455e;border-radius:7px}#alerts-form input[type=number]{width:75px}#alert-events{font-size:13px;margin-top:12px}#metadata-form{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}#metadata-form input,#metadata-form select,#metadata-form textarea{background:#0b1220;color:#fff;border:1px solid #34455e;border-radius:7px;padding:9px;max-width:100%}#manage-name,#rename-target{background:#0b1220;border:1px solid #34455e;border-radius:7px;padding:9px;color:white;max-width:100%}#add-panel[hidden]{display:none}#create-node{display:flex;gap:9px;flex-wrap:wrap}#create-node input{padding:10px;color:#fff;background:#0b1220;border:1px solid #34455e;border-radius:8px;flex:1;min-width:170px}#install-command{width:100%;background:#0b1220;color:#cee4ff;padding:10px;border:1px solid #34455e;border-radius:8px}#traffic-bars .item{display:flex;gap:8px;align-items:center;margin:8px 0;font-size:12px}#traffic-bars .track{background:#2b3b50;height:9px;flex:1;border-radius:4px}#traffic-bars .value{height:100%;border-radius:4px;background:#298be8}*{box-sizing:border-box}body{background:#0b1220;color:#eaf1fc;font:15px system-ui,sans-serif;margin:0}header{display:flex;justify-content:space-between;align-items:center;background:#121f33;padding:12px 5%}main{max-width:1100px;margin:28px auto;padding:0 18px}button{background:#293b58;border:0;color:white;padding:8px 14px;border-radius:8px;cursor:pointer}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stats>div,.node{background:#17243a;border:1px solid #2a3b53;border-radius:12px;padding:18px}.stats small,.stats strong{display:block}.stats small,.muted,.toolbar span{color:#97a6bc}.stats strong{font-size:27px;margin-top:8px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-top:26px}.node{margin:10px 0}.node-head,.metric-row{display:flex;justify-content:space-between;gap:12px}.node-head{font-weight:bold;margin-bottom:15px}.pill{font-size:12px}.pill.ok{color:#5ad6a3}.pill.bad{color:#fc8892}.meters{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.metric-row{font-size:13px;margin-bottom:6px}.bar{height:7px;border-radius:7px;background:#2b3b50;overflow:hidden}.fill{height:100%;background:#388add}.meta{font-size:12px;color:#a3b3c9;margin-top:14px;overflow-wrap:anywhere}.history-panel{background:#17243a;border:1px solid #2a3b53;border-radius:12px;padding:18px;margin-top:20px}.history-controls{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.history-controls select{background:#0b1220;color:white;border:1px solid #34455e;padding:8px;border-radius:7px}canvas{width:100%;height:auto}@media(max-width:600px){.meters{grid-template-columns:1fr}.stats strong{font-size:23px}.stats>div{padding:12px}}`
const appJS=`const $=x=>document.getElementById(x);
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function metric(label,n){n=Math.max(0,Math.min(100,Number(n)||0));return '<div><div class="metric-row"><span>'+label+'</span><b>'+n.toFixed(1)+'%</b></div><div class="bar"><div class="fill" style="width:'+n+'%"></div></div></div>'}
function formatBytes(n){if(!n)return '0 B';const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return n.toFixed(i?1:0)+' '+units[i]}
let prevNames="";let cachedNodes=[];async function refresh(){try{const r=await fetch('/api/v1/nodes',{cache:'no-store'});if(r.status===401){location.href='/login';return}if(!r.ok)throw Error('HTTP '+r.status);const nodes=await r.json();nodes.sort((a,b)=>(a.group||"").localeCompare(b.group||"")||(a.display_name||a.name).localeCompare(b.display_name||b.name));cachedNodes=nodes;updateGroupOptions(nodes);const names=nodes.map(n=>n.name).join('|');if(names!==prevNames){prevNames=names;const ed=$("metadata-name"),old=ed.value;ed.replaceChildren(...nodes.map(n=>new Option(n.display_name||n.name,n.name)));if(nodes.some(n=>n.name===old))ed.value=old;loadMetadata();const sel=$('history-name');const manage=$('manage-name');const was=manage.value;manage.replaceChildren(...nodes.map(n=>new Option(n.name,n.name)));if(nodes.some(n=>n.name===was))manage.value=was;const previousHistoryName=sel.value;sel.replaceChildren(...nodes.map(n=>new Option(n.name,n.name)));if(nodes.some(n=>n.name===previousHistoryName))sel.value=previousHistoryName;drawHistory();}const up=nodes.filter(n=>n.online).length;$('total').textContent=nodes.length;$('online').textContent=up;$('offline').textContent=nodes.length-up;$('nodes').innerHTML=filteredNodes(nodes).map(n=>renderNode(n)).join('')||'<p>尚无节点。请安装 Agent 并连接到服务端。</p>';$('updated').textContent='更新：'+new Date().toLocaleTimeString()}catch(e){$('updated').textContent='获取失败：'+e.message}}
async function drawHistory(){const name=$('history-name').value;if(!name)return;try{const r=await fetch('/api/v1/history?name='+encodeURIComponent(name)+'&hours='+encodeURIComponent($('history-hours').value));if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();const canvas=$('history-chart');const ctx=canvas.getContext('2d');const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#34455e';ctx.lineWidth=1;for(let y=0;y<=100;y+=25){const py=20+(100-y)/100*(h-50);ctx.beginPath();ctx.moveTo(40,py);ctx.lineTo(w-15,py);ctx.stroke();ctx.fillStyle='#a6b5c9';ctx.font='12px sans-serif';ctx.fillText(y+'%',4,py+4)}const metric=$('history-metric').value;if(data.length){const lo=data[0].time,hi=Math.max(lo+1,data[data.length-1].time);ctx.beginPath();ctx.strokeStyle='#47a0f5';ctx.lineWidth=2;data.forEach((p,i)=>{const x=40+(p.time-lo)/(hi-lo)*(w-55),y=20+(100-p[metric])/100*(h-50);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}$('history-status').textContent=data.length+' 个采样区间';drawTraffic()}catch(e){$('history-status').textContent=e.message}}
['history-name','history-hours','history-metric'].forEach(k=>document.addEventListener('change',e=>{if(e.target.id===k)drawHistory()}));async function drawTraffic(){const name=$('history-name').value;if(!name)return;try{const r=await fetch('/api/v1/traffic?name='+encodeURIComponent(name)+'&hours='+encodeURIComponent($('history-hours').value));if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();$('traffic-summary').textContent='接收 ↓ '+formatBytes(d.rx)+' · 发送 ↑ '+formatBytes(d.tx)+'（统计范围内的采样增量）';const max=Math.max(1,...d.buckets.map(b=>b.rx+b.tx));$('traffic-bars').innerHTML=d.buckets.slice(-24).map(b=>'<div class="item"><span>'+new Date(b.time*1000).toLocaleString()+'</span><div class="track"><div class="value" style="width:'+Math.round((b.rx+b.tx)/max*100)+'%"></div></div><span>'+formatBytes(b.rx+b.tx)+'</span></div>').join('')}catch(e){$('traffic-summary').textContent=e.message}}
$('add-node').addEventListener('click',()=>{switchView('settings');$('add-panel').hidden=false;$('server-url').value=location.origin.startsWith('https://')?location.origin:''});
$('create-node').addEventListener('submit',async e=>{e.preventDefault();const name=$('node-name').value.trim(),url=$('server-url').value.trim().replace(/\/$/,'');if(!/^[a-zA-Z0-9_-]{1,64}$/.test(name)||!/^https:\/\/[a-zA-Z0-9.-]+(?::[0-9]+)?$/.test(url)){$('create-status').textContent='需要合法节点名称和 HTTPS 域名';return}if(!confirm('确定创建或轮换节点 '+name+' 的令牌吗？旧令牌会立即失效。'))return;try{const r=await fetch('/api/v1/tokens',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();const installer='https://raw.githubusercontent.com/sockc/Monitor/main/scripts/install-release.sh';$('install-command').value='curl -fsSL '+installer+' -o monitor-install.sh && sudo env MONITOR_SERVER='+url+' MONITOR_NODE_NAME='+name+' MONITOR_AGENT_TOKEN='+data.token+' bash monitor-install.sh agent';$('create-status').textContent='专属命令已生成，请妥善保管（令牌仅显示一次）';refresh()}catch(err){$('create-status').textContent=err.message}});
$('copy-command').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('install-command').value);$('create-status').textContent='已复制到剪贴板'}catch(e){$('create-status').textContent='复制失败，请手动复制'}});
async function manage(action){const name=$('manage-name').value;if(!name)return;let new_name='';if(action==='rename'){new_name=$('rename-target').value.trim();if(!/^[a-zA-Z0-9_-]{1,64}$/.test(new_name)){$('manage-status').textContent='新名称无效';return}}if(!confirm('确认对 '+name+' 执行 '+action+'？此操作可能造成 Agent 离线。'))return;try{const r=await fetch('/api/v1/node-manage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,name,new_name})});if(!r.ok)throw Error(await r.text());$('manage-status').textContent='操作成功。重命名后需重新签发令牌并更新 Agent。';prevNames='';refresh()}catch(e){$('manage-status').textContent=e.message}}
$('rename-node').addEventListener('click',()=>manage('rename'));$('revoke-node').addEventListener('click',()=>manage('revoke'));$('delete-node').addEventListener('click',()=>manage('delete'));
function loadMetadata(){const n=cachedNodes.find(x=>x.name===$("metadata-name").value);if(!n)return;$("metadata-display").value=n.display_name||"";$("metadata-group").value=n.group||"";$("metadata-notes").value=n.notes||""}
$("metadata-name").addEventListener("change",loadMetadata);
$("metadata-form").addEventListener("submit",async e=>{e.preventDefault();const payload={name:$("metadata-name").value,display_name:$("metadata-display").value,group:$("metadata-group").value,notes:$("metadata-notes").value};try{const r=await fetch("/api/v1/node-metadata",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!r.ok)throw Error(await r.text());$("metadata-status").textContent="已保存";prevNames="";await refresh()}catch(err){$("metadata-status").textContent="保存失败："+err.message}});
function updateGroupOptions(nodes){const el=$('node-group'),value=el.value,groups=[...new Set(nodes.map(n=>n.group).filter(Boolean))].sort();const next=['',...groups];if([...el.options].map(x=>x.value).join('|')!==next.join('|')){el.replaceChildren(new Option('全部分组',''),...groups.map(x=>new Option(x,x)));el.value=value}}
function filteredNodes(nodes){const q=$('node-search').value.trim().toLowerCase(),group=$('node-group').value,order=$('node-order').value;const out=nodes.filter(n=>(!group||n.group===group)&&(!q||[n.name,n.display_name,n.group,n.notes,n.hostname].some(x=>String(x||'').toLowerCase().includes(q))));if(order==='offline')out.sort((a,b)=>Number(a.online)-Number(b.online));if(order==='cpu')out.sort((a,b)=>b.cpu-a.cpu);return out}
['node-search','node-group','node-order'].forEach(id=>$(id).addEventListener('input',()=>{const visible=filteredNodes(cachedNodes);$('nodes').innerHTML=visible.map(n=>renderNode(n)).join('')||'<p>没有匹配的服务器</p>'}));
let currentLayout='cards';
try{const saved=localStorage.getItem('monitor-node-layout');if(['cards','compact','list'].includes(saved))currentLayout=saved}catch(e){}
function updateLayout(){const container=$('nodes');container.classList.add('server-grid');container.dataset.layout=currentLayout;document.querySelectorAll('.layout-button').forEach(b=>{const active=b.dataset.layout===currentLayout;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
document.querySelectorAll('.layout-button').forEach(b=>b.addEventListener('click',()=>{currentLayout=b.dataset.layout;try{localStorage.setItem('monitor-node-layout',currentLayout)}catch(e){}updateLayout();$('nodes').innerHTML=filteredNodes(cachedNodes).map(renderNode).join('')||'<p>没有匹配的服务器</p>'}));
updateLayout();
function renderNode(n){return '<article class="node"><div class="node-head"><span>'+esc(n.display_name||n.name)+'</span><span class="pill '+(n.online?'ok':'bad')+'">'+(n.online?'● 在线':'● 离线')+'</span></div><div class="meters">'+metric('CPU',n.cpu)+metric('内存',n.memory)+metric('磁盘 /',n.disk)+'</div><div class="meta">'+esc(n.group||'未分组')+' · '+esc(n.name)+' · ↓'+formatBytes(n.rx_speed)+'/s ↑'+formatBytes(n.tx_speed)+'/s</div></article>'}
async function alertsLoad(){try{const r=await fetch('/api/v1/alerts');if(!r.ok)return;const d=await r.json(),a=d.settings;$('a-offline').value=a.offline_seconds;$('a-cpu').value=a.cpu_threshold;$('a-memory').value=a.memory_threshold;$('a-disk').value=a.disk_threshold;$('a-duration').value=a.duration_seconds;$('a-webhook').value=a.webhook||'';renderAlerts(d.events)}catch(e){$('alerts-status').textContent=e.message}}
function renderAlerts(items){$('alert-events').replaceChildren(...items.slice(0,30).map(e=>{const x=document.createElement('p');x.textContent=(e.end?'已恢复':'告警中')+' · '+e.node+' · '+e.kind+' · '+new Date(e.start*1000).toLocaleString();return x}))}
$('alerts-form').addEventListener('submit',async e=>{e.preventDefault();const payload={offline_seconds:Number($('a-offline').value),cpu_threshold:Number($('a-cpu').value),memory_threshold:Number($('a-memory').value),disk_threshold:Number($('a-disk').value),duration_seconds:Number($('a-duration').value),webhook:$('a-webhook').value.trim()};try{const r=await fetch('/api/v1/alerts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error(await r.text());$('alerts-status').textContent='已保存'}catch(err){$('alerts-status').textContent=err.message}});
function switchView(view){for(const el of document.querySelectorAll('.view'))el.hidden=el.id!=='view-'+view;for(const b of document.querySelectorAll('.nav-btn')){const active=b.dataset.view===view;b.classList.toggle('selected',active);b.setAttribute('aria-current',active?'page':'false')}if(view==='statistics')drawHistory();if(view==='alerts')refreshAlertEvents()}
document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
async function refreshAlertEvents(){try{const r=await fetch('/api/v1/alerts');if(r.ok)renderAlerts((await r.json()).events)}catch(e){}}
switchView('overview');refresh();alertsLoad();setInterval(refresh,5000);setInterval(drawHistory,30000);setInterval(async()=>{try{const r=await fetch('/api/v1/alerts');if(r.ok)renderAlerts((await r.json()).events)}catch(e){}},30000);`
